INSERT INTO "profile" ("id","headline","name","role","intro","bio","portrait_asset_id","links","updated_at") VALUES('main','Beyond the Answer.','Sihyeon Ham, 함시현','UI/UX 디자이너, 기획자','<p>안녕하세요,</p><p><em>UIUX 디자이너, 기획자 </em><strong>함시현</strong><em>입니다.</em></p><p>주어진 답에 머물지 않고, 더 나은 방향을 계속해서 설계합니다.</p>','초등학교 방과 후 교실에서 포토샵에 흥미를 가진 이후, 2014년부터 계속 활동하고 있습니다.',NULL,'[{"label":"hampenta@icloud.com","url":"mailto:hampenta@icloud.com"},{"label":"010 2672 1912","url":"tel:010-2672-1912"},{"label":"서울특별시, 강서구","url":"#profile"}]','2026-05-20 06:02:34');
